public class BZip2CompressorInputStream_read_TriageGen1Test {

    /**
     * Helper to create a valid BZip2 stream for testing.
     * BZip2 format requires a specific header. 
     * 'BZh9' is the standard magic number for BZip2.
     */
    private InputStream createMockBZip2Stream(byte[] data) throws IOException {
        // Minimal valid BZip2 stream is complex to hand-craft.
        // For unit testing the 'read' logic, we use a real BZip2 compressed byte array.
        // However, since we are testing the internal 'read' method logic of the wrapper,
        // we can use a real stream.
        // For the sake of this test, we assume the input is valid BZip2.
        return new ByteArrayInputStream(data);
    }

    @Test
    public void testRead_OffsLessThanZero() throws IOException {
        try (InputStream is = new ByteArrayInputStream(new byte[0]);
             BZip2CompressorInputStream bz = new BZip2CompressorInputStream(is)) {
            try {
                bz.read(new byte[10], -1, 5);
                fail("Should have thrown IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                assertEquals("offs(-1) < 0.", e.getMessage());
            }
        }
    }

    @Test
    public void testRead_LenLessThanZero() throws IOException {
        try (InputStream is = new ByteArrayInputStream(new byte[0]);
             BZip2CompressorInputStream bz = new BZip2CompressorInputStream(is)) {
            try {
                bz.read(new byte[10], 0, -1);
                fail("Should have thrown IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                assertEquals("len(-1) < 0.", e.getMessage());
            }
        }
    }

    @Test
    public void testRead_BoundsExceeded() throws IOException {
        try (InputStream is = new ByteArrayInputStream(new byte[0]);
             BZip2CompressorInputStream bz = new BZip2CompressorInputStream(is)) {
            try {
                bz.read(new byte[10], 5, 6); // 5 + 6 = 11 > 10
                fail("Should have thrown IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                assertEquals("offs(5) + len(6) > dest.length(10).", e.getMessage());
            }
        }
    }

    @Test
    public void testRead_StreamClosed() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        BZip2CompressorInputStream bz = new BZip2CompressorInputStream(is);
        bz.close();
        try {
            bz.read(new byte[10], 0, 5);
            fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("stream closed", e.getMessage());
        }
    }

    @Test
    public void testRead_LenZero() throws IOException {
        // Using a dummy stream that won't actually be read because len is 0
        byte[] bzip2Data = new byte[] { 'B', 'Z', 'h', '1' }; 
        try (InputStream is = new ByteArrayInputStream(bzip2Data);
             BZip2CompressorInputStream bz = new BZip2CompressorInputStream(is)) {
            byte[] dest = new byte[10];
            int result = bz.read(dest, 2, 0);
            assertEquals(0, result);
        }
    }

